    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(LedgerJournalSetup, LedgerJournalName), FormDataSourceEventType::InitValue)]
    public static void LedgerJournalName_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormDataSource LedgerJournalName_ds = sender.formRun().dataSource();

        LedgerJournalName ledgerJournalName = LedgerJournalName_ds.cursor();

        if(ledgerJournalName.METPaymDate == NoYesCombo::Yes)
        {
            LedgerJournalName.METInvoiceDtPostingDt = METInvoiceDtPostingDt::PostingDate;

        }
        else if(LedgerJournalName.METPaymDate == NoYesCombo::No)
        {
            LedgerJournalName.METInvoiceDtPostingDt = METInvoiceDtPostingDt::InvoiceDate;

        }
    }

