    /// <summary>
    /// On Changing the Toggle Control the payment date or Invoice Date will be determined
    /// </summary>
    /// <param name="sender">LedgerJournalSetup </param>
    /// <param name="e">Data Field details</param>
    [FormDataFieldEventHandler(formDataFieldStr(LedgerJournalSetup, LedgerJournalName, METPaymDate), FormDataFieldEventType::Modified)]
    public static void METPaymDate_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        //Retrieve the Journal Transaction current record detailsv
        FormDataSource LedgerJournalName_ds = sender.datasource();

        //Journal Name 
        LedgerJournalName ledgerJournalName = LedgerJournalName_ds.cursor();

        //Payment Date Toggle Control buffer
        NoYesCombo paymDtChk = LedgerJournalName::find(LedgerJournalName.JournalName).METPaymDate;

        //Validate if the Payment date toggle control is set to Yes
        if(ledgerJournalName.METPaymDate == NoYesCombo::Yes)
        {
            LedgerJournalName.METInvoiceDtPostingDt = METInvoiceDtPostingDt::PostingDate;

        }
        else if(LedgerJournalName.METPaymDate == NoYesCombo::No)
        {
            LedgerJournalName.METInvoiceDtPostingDt = METInvoiceDtPostingDt::InvoiceDate;

        }
    }
